<?php
session_name('anytour_manager_panel');
session_set_cookie_params(['lifetime'=>60*60*12,'path'=>'/max-search/manager/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);
session_start();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>AnyTour — Workspace V2</title><style>
*{box-sizing:border-box}body{margin:0;font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f4f6f8;color:#17202a}.workspace{height:100vh;display:grid;grid-template-columns:320px minmax(420px,1fr) 340px}.zone{min-width:0;background:#fff}.inboxZone{border-right:1px solid #e5e9ee;display:flex;flex-direction:column}.conversationZone{display:flex;flex-direction:column;background:#f6f8fa}.leadZone{border-left:1px solid #e5e9ee;overflow:auto}.zoneHead{padding:15px 16px;border-bottom:1px solid #e7ebef;background:#fff}.brand{font-size:18px;font-weight:750}.muted{color:#74808d;font-size:12px}.queueTabs{display:flex;gap:6px;overflow:auto;margin-top:12px}.queueTabs button,.actionBtn,.sendBtn{border:0;border-radius:9px;background:#edf1f4;padding:8px 10px;cursor:pointer;white-space:nowrap}.queueTabs button.active,.actionBtn.primary,.sendBtn{background:#17202a;color:#fff}.inboxList{overflow:auto;flex:1}.leadItem{padding:12px 14px;border-bottom:1px solid #eef1f4;cursor:pointer}.leadItem:hover,.leadItem.active{background:#f3f7fb}.leadName{font-weight:700;display:flex;justify-content:space-between;gap:8px}.pill{font-size:10px;padding:2px 6px;border-radius:999px;background:#e9edf1;font-weight:600}.pill.waiting_manager{background:#fff0bd}.pill.manager{background:#daf7e5}.preview{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px}.conversationHead{display:flex;justify-content:space-between;align-items:center;gap:10px}.actions{display:flex;gap:6px;flex-wrap:wrap}.messages{flex:1;overflow:auto;padding:18px;display:flex;flex-direction:column;gap:10px}.msg{max-width:78%;border-radius:14px;padding:10px 12px;white-space:pre-wrap;word-break:break-word;box-shadow:0 1px 2px #00000010}.msg.customer{align-self:flex-start;background:#fff}.msg.ai{align-self:flex-end;background:#e8f2ff}.msg.manager{align-self:flex-end;background:#dcfce7}.msgMeta{font-size:10px;color:#7b8793;margin-top:5px}.attachments{display:flex;gap:7px;flex-direction:column;margin-top:8px}.attachments img,.attachments video{max-width:100%;max-height:340px;border-radius:10px}.attachments audio{max-width:100%}.attachments a{color:#185aa6}.composer{padding:12px;background:#fff;border-top:1px solid #e5e9ee;display:flex;gap:8px}.composer textarea{flex:1;min-height:42px;max-height:120px;resize:none;border:1px solid #d5dce3;border-radius:11px;padding:10px;font:inherit}.leadCard{padding:16px}.section{padding:14px 0;border-bottom:1px solid #edf0f2}.sectionTitle{font-weight:750;margin-bottom:9px}.field{margin:7px 0}.label{display:block;color:#7b8793;font-size:11px}.value{font-weight:550}.tripGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stageSelect{width:100%;padding:9px;border:1px solid #d5dce3;border-radius:9px;background:#fff}.tagList{display:flex;flex-wrap:wrap;gap:6px}.tagChoice{display:flex;align-items:center;gap:5px;border:1px solid #d9dfe5;border-radius:999px;padding:5px 8px;background:#fff}.empty{margin:auto;color:#8a949e;text-align:center;padding:30px}.mobileLeadBtn,.mobileBack{display:none}.error{padding:10px;background:#fff1f1;color:#8a1b1b;border-radius:9px}.hidden{display:none!important}@media(max-width:900px){.workspace{display:block}.inboxZone{height:100vh}.conversationZone{position:fixed;inset:0;transform:translateX(100%);transition:.18s;z-index:3}.conversationZone.open{transform:none}.leadZone{position:fixed;inset:0 0 0 14%;z-index:4;transform:translateX(100%);transition:.18s;border-left:1px solid #dfe4e8}.leadZone.open{transform:none}.mobileLeadBtn,.mobileBack{display:inline-block}.msg{max-width:90%}}
</style></head><body><div class="workspace">
<aside class="zone inboxZone"><div class="zoneHead"><div class="brand">Лиды</div><div id="managerName" class="muted">Manager Workspace V2</div><div class="queueTabs"><button data-q="waiting" class="active">Новые</button><button data-q="mine">Мои</button><button data-q="all">Все</button><button data-q="closed">Закрытые</button></div></div><div id="inboxList" class="inboxList"><div class="empty">Загрузка…</div></div></aside>
<main id="conversationZone" class="zone conversationZone"><div class="zoneHead conversationHead"><div><button id="mobileBack" class="mobileBack actionBtn">‹</button><span id="conversationTitle" class="brand">Выберите лид</span><div id="conversationMeta" class="muted"></div></div><div class="actions"><button id="mobileLeadBtn" class="mobileLeadBtn actionBtn">Карточка</button><span id="conversationActions"></span></div></div><div id="messages" class="messages"><div class="empty">Оригинальная переписка туриста появится здесь</div></div><form id="composer" class="composer hidden"><textarea id="replyText" placeholder="Ответ менеджера"></textarea><button class="sendBtn">Отправить</button></form></main>
<aside id="leadZone" class="zone leadZone"><div class="zoneHead"><div class="brand">Карточка лида</div><div class="muted">Продажи отдельно от технического статуса</div></div><div id="leadCard" class="leadCard"><div class="empty">Выберите лид</div></div></aside>
</div><script>
const S={csrf:'',manager:null,current:0,queue:'waiting',pipeline:{stages:[],tags:[]},detail:null};const $=id=>document.getElementById(id);function esc(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}
async function api(action,data={}){const r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf:S.csrf,...data})});const j=await r.json().catch(()=>({ok:false}));if(r.status===401){location.href='index.php';throw new Error('unauthorized')}return j}
async function pipe(action,data={}){const r=await fetch('pipeline-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf:S.csrf,...data})});const j=await r.json().catch(()=>({ok:false}));if(r.status===401){location.href='index.php';throw new Error('unauthorized')}return j}
function statusText(s){return{ai:'AI',waiting_manager:'Ждёт менеджера',manager:'У менеджера',closed:'Закрыт'}[s]||s||''}
async function boot(){const me=await api('me').catch(()=>null);if(!me?.ok)return;S.csrf=me.csrf;S.manager=me.manager;$('managerName').textContent=(S.manager.display_name||S.manager.login)+' · Workspace V2';const cat=await pipe('catalog');if(cat.ok)S.pipeline={stages:cat.stages||[],tags:cat.tags||[]};await loadList()}
document.querySelectorAll('.queueTabs button').forEach(b=>b.onclick=async()=>{document.querySelectorAll('.queueTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');S.queue=b.dataset.q;await loadList()});
async function loadList(){const j=await api('list',{queue:S.queue,project_key:'*'});const box=$('inboxList');box.innerHTML='';if(!j.ok||!j.conversations?.length){box.innerHTML='<div class="empty">Лидов в этой очереди нет</div>';return}j.conversations.forEach(c=>{const el=document.createElement('div');el.className='leadItem'+(Number(c.id)===S.current?' active':'');el.innerHTML=`<div class="leadName"><span>${esc(c.display_name||'Турист')}</span><span class="pill ${esc(c.status)}">${esc(statusText(c.status))}</span></div><div class="muted">${esc([c.project_name||c.project_key,c.source_name,(c.channel||'').toUpperCase()].filter(Boolean).join(' · '))}</div><div class="preview">${esc(c.last_text||'')}</div>`;el.onclick=()=>openConversation(c.id);box.appendChild(el)})}
function renderAttachments(root,items){if(!Array.isArray(items)||!items.length)return;const wrap=document.createElement('div');wrap.className='attachments';items.forEach(a=>{const url=String(a?.url||'');let n;if(a.type==='image'&&url){n=document.createElement('img');n.src=url;n.loading='lazy'}else if(a.type==='video'&&url){n=document.createElement('video');n.src=url;n.controls=true}else if(a.type==='audio'&&url){n=document.createElement('audio');n.src=url;n.controls=true}else{n=document.createElement('a');n.textContent='📎 '+(a.name||'Вложение');if(url){n.href=url;n.target='_blank';n.rel='noopener'}}wrap.appendChild(n)});root.appendChild(wrap)}
async function openConversation(id){S.current=Number(id);const [d,p]=await Promise.all([api('detail',{conversation_id:S.current}),pipe('detail',{conversation_id:S.current})]);if(!d.ok||!p.ok)return;S.detail={...d,lead:p};const c=d.conversation;$('conversationZone').classList.add('open');$('conversationTitle').textContent=c.display_name||'Турист';$('conversationMeta').textContent=[c.project_name||c.project_key,c.source_name,(c.channel||'').toUpperCase(),statusText(c.status),c.manager_name].filter(Boolean).join(' · ');const box=$('messages');box.innerHTML='';(d.messages||[]).forEach(m=>{const n=document.createElement('div');const who=m.sender_type==='customer'?'customer':m.sender_type==='manager'?'manager':'ai';n.className='msg '+who;const body=document.createElement('div');body.textContent=m.text||'';n.appendChild(body);renderAttachments(n,m.attachments||[]);const meta=document.createElement('div');meta.className='msgMeta';meta.textContent=(who==='customer'?'Турист':who==='manager'?'Менеджер':'AI')+' · '+(m.created_at||'');n.appendChild(meta);box.appendChild(n)});box.scrollTop=box.scrollHeight;renderLeadCard(p,c);renderActions(c);await loadList()}
function renderActions(c){const root=$('conversationActions');root.innerHTML='';const own=Number(c.manager_id)===Number(S.manager.id)&&c.status==='manager';if((c.status==='waiting_manager'||c.status==='ai')&&!c.manager_id&&(S.manager.role==='admin'||S.manager.is_working))action('Взять','primary',()=>change('take'));if(own){action('Вернуть AI','',()=>change('release'));action('Закрыть','',()=>change('close'))}if(c.status==='closed')action('Переоткрыть','primary',()=>change('reopen'));$('composer').classList.toggle('hidden',!own)}
function action(text,cl,fn){const b=document.createElement('button');b.className='actionBtn '+cl;b.type='button';b.textContent=text;b.onclick=fn;$('conversationActions').appendChild(b)}async function change(a){const j=await api(a,{conversation_id:S.current});if(j.ok)await openConversation(S.current)}
function val(v){return(v===null||v===undefined||v==='')?'—':String(v)}function tripField(label,value){return`<div class="field"><span class="label">${esc(label)}</span><span class="value">${esc(val(value))}</span></div>`}
function renderLeadCard(p,c){const pipeline=p.pipeline||{},trip=p.trip||{},contact=p.contact||{},source=p.source||{},handoff=p.handoff||{};const selected=new Set((pipeline.tags||[]).map(x=>Number(x.id)));$('leadCard').innerHTML=`<div class="section"><div class="sectionTitle">Продажа</div><label class="label" for="leadStage">Этап сделки</label><select id="leadStage" class="stageSelect">${S.pipeline.stages.map(s=>`<option value="${esc(s.stage_key)}" ${pipeline.stage?.stage_key===s.stage_key?'selected':''}>${esc(s.display_name)}</option>`).join('')}</select><div class="label" style="margin-top:10px">Теги</div><div id="leadTags" class="tagList">${S.pipeline.tags.length?S.pipeline.tags.map(t=>`<label class="tagChoice"><input type="checkbox" value="${Number(t.id)}" ${selected.has(Number(t.id))?'checked':''}>${esc(t.display_name)}</label>`).join(''):'<span class="muted">Теги пока не настроены</span>'}</div></div><div class="section"><div class="sectionTitle">Поездка</div><div class="tripGrid">${tripField('Вылет',trip.city)}${tripField('Куда',trip.country)}${tripField('Взрослые',trip.adults)}${tripField('Дети',trip.children)}${tripField('Отель',trip.stars?trip.stars+'★':null)}${tripField('Питание',trip.meal)}${tripField('Ночи',trip.nights)}${tripField('Дата',trip.date)}</div></div><div class="section"><div class="sectionTitle">Контакт</div>${tripField('Телефон',contact.phone)}${tripField('Email',contact.email)}</div><div class="section"><div class="sectionTitle">Источник и handoff</div>${tripField('Проект',source.project)}${tripField('Источник',source.source)}${tripField('Канал',source.channel)}${tripField('Технический статус',statusText(handoff.technical_status))}${tripField('Менеджер',handoff.manager_name)}</div>`;const stage=$('leadStage');if(stage)stage.onchange=async()=>{const j=await pipe('set_stage',{conversation_id:S.current,stage_key:stage.value});if(!j.ok)alert('Не удалось изменить этап')};document.querySelectorAll('#leadTags input').forEach(x=>x.onchange=saveTags)}
async function saveTags(){const ids=[...document.querySelectorAll('#leadTags input:checked')].map(x=>Number(x.value));const j=await pipe('set_tags',{conversation_id:S.current,tag_ids:ids});if(!j.ok)alert('Не удалось сохранить теги')}
$('composer').onsubmit=async e=>{e.preventDefault();const text=$('replyText').value.trim();if(!text)return;const j=await api('send',{conversation_id:S.current,text});if(j.ok){$('replyText').value='';await openConversation(S.current)}};$('mobileBack').onclick=()=>$('conversationZone').classList.remove('open');$('mobileLeadBtn').onclick=()=>$('leadZone').classList.add('open');$('leadZone').onclick=e=>{if(innerWidth<=900&&e.target===$('leadZone'))$('leadZone').classList.remove('open')};boot();
</script></body></html>
